def is_valid_time_range(s):
    if len(s) != 11 or s[2] != ':' or s[5] != '-' or s[8] != ':':
        return False
    h1, m1, h2, m2 = s[0:2], s[3:5], s[6:8], s[9:11]
    if not (h1.isdigit() and m1.isdigit() and h2.isdigit() and m2.isdigit()):
        return False
    h1, m1, h2, m2 = int(h1), int(m1), int(h2), int(m2)
    if not (0 <= h1 <= 23 and 0 <= m1 <= 59 and 0 <= h2 <= 23 and 0 <= m2 <= 59):
        return False
    return h1 * 60 + m1 < h2 * 60 + m2

