def find_repeated_substrings_of_length(s, k):
    if k <= 0 or k > len(s):
        return []
    seen_once = set()
    seen_multi = set()
    order = []
    for i in range(len(s) - k + 1):
        sub = s[i:i + k]
        if sub in seen_multi:
            continue
        if sub in seen_once:
            seen_multi.add(sub)
            order.append(sub)
        else:
            seen_once.add(sub)
    return order

